def _document(name, version, page, text, controlling=False):
    """Declare source identity; complete body/layout is added after case assembly."""
    slug = re.sub(r"[^a-z0-9]+", "-", name.lower()).strip("-")
    return {
        "name": name, "version": version, "page": page, "text": text,
        "classification": name, "sourceHash": "pending-content-hash",
        "receivedAt": "2026-08-28T16:00:00Z", "controlling": controlling,
        "sourceFormat": "Pending generated source", "visionEligible": True,
        "extractionTargets": EXTRACTION_TARGETS.get(name, ["document identity", "material facts", "dates", "exception language"]),
        "assetSlug": slug,
    }
