# Replace the old one-line fixture summaries with complete, source-authored
# instruments before any agent or API route can access the packet.
for _transaction in TRANSACTIONS.values():
    for _source_document in _transaction["documents"]:
        populate_document(_transaction, _source_document)
        _texts = page_texts(_source_document["blocks"])
        _source_document["pageCount"] = len(_texts)
        _source_document["sourcePages"] = [{"number": index, "text": text} for index, text in enumerate(_texts, 1)]

def get_transaction(case_id):
    item=TRANSACTIONS.get(case_id)
    if not item:return None
    transaction=deepcopy(item)
    for document in transaction["documents"]:
        base=f"/demo-packet/{case_id}/{document['assetSlug']}";document["imageUrl"]=f"{base}.png?v={document['sourceHash'][:10]}";document["pdfUrl"]=f"{base}.pdf?v={document['sourceHash'][:10]}"
        for page in document["sourcePages"]:
            suffix = "" if page["number"] == 1 else f"-p{page['number']}"
            page["imageUrl"] = f"{base}{suffix}.png?v={document['sourceHash'][:10]}"
    return transaction
def list_cases():
    return [{key:value[key] for key in ("id","property","closingDate","side")}|{"documents":len(value["documents"])} for value in TRANSACTIONS.values()]
